def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise ValueError("value cannot be None")
    try:
        lat = value.lat
        lon = value.lon
        time = value.time
    except AttributeError as exc:
        raise TypeError("value must have attributes 'lat', 'lon', and 'time'") from exc

    # Ensure latitude and longitude are numeric
    try:
        lat = float(lat)
        lon = float(lon)
    except (TypeError, ValueError) as exc:
        raise TypeError("latitude and longitude must be numeric") from exc

    # Convert time to ISO format string
    if hasattr(time, "isoformat"):
        time_str = time.isoformat()
    else:
        raise TypeError("time attribute must support isoformat()")

    return {"lat": lat, "lon": lon, "time": time_str}

