def keys(self):
    """Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to retrieve the underlying record storage
        record = getattr(self, "_record", None)
        if record is None:
            return []

        # If the record is a dictionary, return its keys
        if isinstance(record, dict):
            return list(record.keys())

        # If the record is a list of (key, value) tuples, extract keys
        if isinstance(record, list):
            return [k for k, _ in record if isinstance(k, str)]

        # If the record provides a keys() method (e.g., OrderedDict), use it
        if hasattr(record, "keys"):
            return list(record.keys())

        # Fallback: try to iterate over the record and collect string keys
        return [k for k in record if isinstance(k, str)]

    except Exception:
        # In case of any unexpected error, return an empty list
        return []

