def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Helper to get the underlying items container
    items = getattr(self, "_items", self)

    # If no keys are provided, return all values
    if not keys:
        if isinstance(items, dict):
            return list(items.values())
        if isinstance(items, (list, tuple)):
            return list(items)
        # Try to iterate over any iterable
        try:
            return list(items)
        except TypeError:
            raise TypeError(
                f"Cannot iterate over items of type {type(items).__name__} to retrieve values."
            )

    # If keys are provided, filter accordingly
    results = []
    for key in keys:
        try:
            if isinstance(key, int):
                # Treat as an index
                if isinstance(items, (list, tuple)):
                    results.append(items[key])
                else:
                    raise TypeError(
                        f"Cannot index non-list items with integer key {key}."
                    )
            else:
                # Treat as a key lookup
                if isinstance(items, dict):
                    results.append(items[key])
                else:
                    # Attempt to find a tuple/list with the key as first element
                    found = False
                    for item in items:
                        if isinstance(item, (list, tuple)) and len(item) > 1 and item[0] == key:
                            results.append(item[1])
                            found = True
                            break
                    if not found:
                        raise KeyError(key)
        except (IndexError, KeyError, TypeError):
            # Skip invalid keys silently
            continue

    return results

