def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate class name
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"Invalid class name: {name!r}")

    # Validate fields iterable
    try:
        field_list = list(fields)
    except TypeError:
        raise TypeError("fields must be an iterable of field names")

    for f in field_list:
        if not isinstance(f, str) or not f.isidentifier():
            raise TypeError(f"Invalid field name: {f!r}")

    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Build namespace for the new class
    namespace = {}
    namespace['__slots__'] = tuple(field_list)
    namespace['srid_map'] = srid_map

    # Define __init__ to accept positional or keyword arguments
    def __init__(self, *args, **kwargs):
        if len(args) > len(field_list):
            raise TypeError(f"Expected at most {len(field_list)} positional arguments, got {len(args)}")
        # Assign positional arguments
        for field_name, value in zip(field_list, args):
            setattr(self, field_name, value)
        # Assign remaining fields from kwargs
        for field_name in field_list[len(args):]:
            if field_name in kwargs:
                setattr(self, field_name, kwargs.pop(field_name))
            else:
                raise TypeError(f"Missing value for field {field_name!r}")
        if kwargs:
            raise TypeError(f"Unexpected keyword arguments: {', '.join(kwargs)}")

    namespace['__init__'] = __init__

    # Optional __repr__ for debugging
    def __repr__(self):
        values = ', '.join(f"{fname}={getattr(self, fname)!r}" for fname in field_list)
        return f"{name}({values})"

    namespace['__repr__'] = __repr__

    # Create the new subclass of Point
    try:
        cls = type(name, (Point,), namespace)
    except Exception as exc:
        raise RuntimeError(f"Failed to create class {name!r}") from exc

    return cls

