def _inline_r_setup(code: str) -> str:
    r"""
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise TypeError("code must be a string")
    try:
        # Common R options that influence reproducibility and output formatting
        options_code = (
            "options(stringsAsFactors = FALSE, scipen = 999, digits = 15)\n"
        )
        return options_code + code
    except Exception as exc:
        raise RuntimeError(f"Failed to set R options: {exc}") from exc

