def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        if seq is None:
            raise TypeError("seq cannot be None")
        # Convert to list to allow shuffling
        try:
            seq_list = list(seq)
        except Exception as e:
            raise TypeError("seq must be an iterable of strings") from e
        # Validate that all elements are strings
        for i, item in enumerate(seq_list):
            if not isinstance(item, str):
                raise TypeError(f"Element at index {i} is not a string")
        # Create a deterministic seed based on the content of the sequence
        seed = hash(tuple(seq_list))
        import random as _random
        rng = _random.Random(seed)
        rng.shuffle(seq_list)
        return seq_list
    except Exception as exc:
        raise RuntimeError(f"Failed to deterministically shuffle sequence: {exc}") from exc

