def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        else:
            def wrapper(*args, **kwargs):
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    # If key function fails, fall back to calling the function
                    return func(*args, **kwargs)
                # Try to retrieve from cache
                try:
                    if lock is None:
                        return cache[k]
                    else:
                        if callable(lock):
                            with lock():
                                return cache[k]
                        else:
                            with lock:
                                return cache[k]
                except KeyError:
                    pass  # key not found
                # Compute value and store in cache
                v = func(*args, **kwargs)
                try:
                    if lock is None:
                        cache[k] = v
                    else:
                        if callable(lock):
                            with lock():
                                cache[k] = v
                        else:
                            with lock:
                                cache[k] = v
                except ValueError:
                    pass  # value too large or cache write error
                return v
        return wrapper
    return decorator

