def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")
    # Validate all elements are classes
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"Element {c!r} is not a class")
    # Compute minimal set: keep a class only if it is not a superclass of any other
    minimal = []
    for c in classes:
        is_super = False
        for d in classes:
            if d is c:
                continue
            try:
                if issubclass(d, c):
                    is_super = True
                    break
            except TypeError:
                # d is not a class, but we already validated
                pass
        if not is_super:
            minimal.append(c)
    return minimal

