def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle special case where the sequence is a class with a Broken base
    try:
        if Broken in getattr(sequence, "__bases__", ()):
            return [sequence]
    except Exception:
        # If we cannot inspect bases, fall back to normal processing
        pass

    # If the sequence is None, nothing to do
    if sequence is None:
        return output

    # Determine if the sequence is an interface declaration
    try:
        cls = sequence.__class__
        # Check for InterfaceClass or Implements in the MRO
        if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
            output.append(sequence)
        else:
            # Assume the sequence is iterable and recurse
            for v in sequence:
                _normalizeargs(v, output)
    except Exception:
        # If any error occurs (e.g., sequence is not iterable), treat it as a single item
        output.append(sequence)

    return output

