    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context to an empty dictionary
    try:
        self.context = {}
    except AttributeError:
        # If the attribute does not exist, create it
        self.context = {}

    # Reinitialize the bins
    try:
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Use the provided initial value if available
            self.bins = self.initial_value
        else:
            # Fall back to the make_bins method if it exists
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                raise AttributeError(
                    "Cannot reset bins: neither 'initial_value' nor 'make_bins' is available."
                )
    except Exception as exc:
        # Wrap any exception to provide clearer context
        raise RuntimeError(f"Failed to reinitialize bins during reset: {exc}") from exc

