def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate the coordinate name
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Ensure the object has an error dictionary
    if not hasattr(self, "_errors") or not isinstance(self._errors, dict):
        raise AttributeError("The object does not contain an '_errors' dictionary")
    # Check that the coordinate exists in the error dictionary
    if coord_name not in self._errors:
        raise KeyError(f"Coordinate '{coord_name}' not found in error dictionary")
    err = self._errors[coord_name]
    # If there is no error array, return an empty list
    if err is None:
        return []
    # Convert to a NumPy array safely
    try:
        arr = np.asarray(err)
    except Exception as exc:
        raise ValueError(f"Error array for coordinate '{coord_name}' could not be converted to a NumPy array: {exc}")
    # Ensure the array is one‑dimensional
    if arr.ndim != 1:
        raise ValueError(f"Error array for coordinate '{coord_name}' must be 1‑D, got {arr.ndim}‑D")
    # If the array is empty, return an empty list
    if arr.size == 0:
        return []
    # Determine indices where the error is finite and non‑zero
    try:
        mask = np.isfinite(arr) & (arr != 0)
    except Exception as exc:
        raise ValueError(f"Could not evaluate error array for coordinate '{coord_name}': {exc}")
    indices = np.where(mask)[0]
    # Return a plain Python list for consistency
    return indices.tolist()

