def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Basic type validation
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            f"last_applied_manifest must be a dict, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            f"observer_schema must be a list, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, dict):
        raise TypeError(
            f"response must be a dict, got {type(response).__name__}"
        )

    for item in observer_schema:
        # Support two forms of schema entry:
        # 1. simple field name: "metadata"
        # 2. tuple of (field_name, nested_schema)
        if isinstance(item, tuple):
            field_name, nested_schema = item
        else:
            field_name, nested_schema = item, None

        # If the field is missing in the manifest, try to initialise it
        if field_name not in last_applied_manifest:
            if field_name in response:
                # Copy the value from the response
                last_applied_manifest[field_name] = response[field_name]
            else:
                # Field not present in the response; skip
                continue

        # If a nested schema is provided, recurse into the appropriate helper
        if nested_schema is not None:
            # Determine the type of the nested structure
            try:
                current_value = last_applied_manifest[field_name]
                resp_value = response.get(field_name)
            except Exception:
                # If we cannot access the values, skip recursion
                continue

            if isinstance(nested_schema, list) and isinstance(current_value, list) and isinstance(resp_value, list):
                # Recurse into list helper
                update_last_applied_manifest_list_from_resp(
                    current_value, nested_schema, resp_value
                )
            elif isinstance(nested_schema, dict) and isinstance(current_value, dict) and isinstance(resp_value, dict):
                # Recurse into dict helper
                update_last_applied_manifest_dict_from_resp(
                    current_value, nested_schema, resp_value
                )
            else:
                # Mismatch between expected and actual types; ignore
                continue
    # The function mutates ``last_applied_manifest`` in place; no return value needed.

