def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Safely access spec, manifest and observer_schema
    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            return
        manifest = getattr(spec, "manifest", [])
        observer_schema = getattr(spec, "observer_schema", {})
    except AttributeError:
        return

    # Ensure manifest is a list
    if not isinstance(manifest, list):
        return

    # Ensure observer_schema is a dict
    if not isinstance(observer_schema, dict):
        observer_schema = {}

    # Default schema to apply
    default_schema = {
        "type": "object",
        "properties": {
            "metadata": {"type": "object"},
            "status": {"type": "object"},
        },
    }

    # Track kinds already processed to avoid duplicate work
    processed_kinds = set(observer_schema.keys())

    for resource in manifest:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind or kind in processed_kinds:
            continue
        # Assign a shallow copy of the default schema for each kind
        observer_schema[kind] = default_schema.copy()
        processed_kinds.add(kind)

    # Update the spec with the new observer_schema
    setattr(spec, "observer_schema", observer_schema)
    return observer_schema

