    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False

        # Handle pyfilesystem2 root objects
        if hasattr(path, "getinfo") and hasattr(path, "listdir"):
            try:
                info = path.getinfo("")
                if not info.is_dir:
                    return False
                files = path.listdir("")
                required = [".ocfl_root", ".ocfl_version"]
                for req in required:
                    if req not in files:
                        return False
                return True
            except Exception:
                return False

        # Handle normal filesystem paths
        p = pathlib.Path(path)
        if not p.exists() or not p.is_dir():
            return False

        required = [".ocfl_root", ".ocfl_version"]
        for req in required:
            if not (p / req).exists():
                return False

        return True
    except Exception:
        return False

