        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic sanity checks
        if inventory is None:
            raise ArgumentError("inventory", "Inventory cannot be None")
        if not isinstance(inventory, dict):
            raise ArgumentError("inventory", f"Expected dict, got {type(inventory).__name__}")

        # Extract spec version if requested
        if extract_spec_version:
            type_val = inventory.get("type")
            if isinstance(type_val, str):
                # Attempt to parse a version number from the type string
                # e.g., "inventory_v2" -> 2
                import re
                match = re.search(r"v(\d+)", type_val)
                if match:
                    try:
                        self.spec_version = int(match.group(1))
                    except ValueError:
                        # If parsing fails, keep the existing spec_version
                        pass

        # Determine required fields based on the current spec_version
        required_fields = ["name", "items"]
        if getattr(self, "spec_version", None) and self.spec_version >= 2:
            required_fields.append("metadata")

        # Check for missing required fields
        missing = [field for field in required_fields if field not in inventory]
        if missing:
            raise ArgumentError(
                "inventory",
                f"Missing required fields: {', '.join(missing)}",
            )

        # Validate the 'items' field
