    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if version is None:
        raise ValueError("version cannot be None")

    result = {}
    try:
        # Handle inventory as a mapping from logical_path to versioned data
        if isinstance(inventory, dict):
            for logical_path, data in inventory.items():
                files = set()
                if isinstance(data, dict):
                    # Direct mapping: version -> file
                    if version in data:
                        files.add(data[version])
                elif isinstance(data, list):
                    for entry in data:
                        if isinstance(entry, dict):
                            if entry.get("version") == version:
                                files.add(entry.get("file"))
                        elif isinstance(entry, tuple) and len(entry) >= 2:
                            v, f = entry[0], entry[1]
                            if v == version:
                                files.add(f)
                if files:
                    result[logical_path] = files

        # Handle inventory as a list of entries
        elif isinstance(inventory, list):
            for entry in inventory:
                if isinstance(entry, dict):
                    if entry.get("version") == version:
                        lp = entry.get("logical_path")
                        f = entry.get("file")
                        if lp is not None and f is not None:
                            result.setdefault(lp, set()).add(f)
