def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")
    # Ensure manifest_files is a set for fast lookup
    manifest_set = set(manifest_files)
    seen_paths = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary")
        for key in ('path', 'hash', 'size'):
            if key not in entry:
                raise ValueError(f"File entry at index {idx} missing required key '{key}'")
        path = entry['path']
        if not isinstance(path, str):
            raise ValueError(f"File entry at index {idx} 'path' must be a string")
        if path in seen_paths:
            raise ValueError(f"Duplicate file path '{path}' in fixity block")
        seen_paths.add(path)
        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity block not present in manifest")
        if not isinstance(entry['hash'], str):
            raise ValueError(f"File entry at index {idx} 'hash' must be a string")
        if not isinstance(entry['size'], int):
            raise ValueError(f"File entry at index {idx} 'size' must be an integer")
    # No unexpected keys in the top-level fixity block
    allowed_keys = {'files'}
    extra_keys = set(fixity.keys()) - allowed_keys
    if extra_keys:
        raise ValueError(f"Unexpected keys in fixity block: {', '.join(sorted(extra_keys))}")
    return True

