def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise ValueError(f"Provided path '{folder}' is not a directory or does not exist")

    try:
        entries = os.listdir(folder)
    except OSError as exc:
        raise RuntimeError(f"Failed to list directory '{folder}': {exc}") from exc

    # Identify basenames that have an XML file
    xml_basenames = set()
    for entry in entries:
        if entry.lower().endswith('.xml'):
            xml_basenames.add(os.path.splitext(entry)[0])

    if not xml_basenames:
        # No XML files found; return empty dict
        return {}

    # Group all files that share a basename present in xml_basenames
    grouped = {basename: [] for basename in xml_basenames}
    for entry in entries:
        basename, _ = os.path.splitext(entry)
        if basename in xml_basenames:
            grouped[basename].append(os.path.join(folder, entry))

    # Optionally remove groups that ended up empty (unlikely)
    grouped = {k: v for k, v in grouped.items() if v}

    return grouped

