def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Validate basename
    if not isinstance(basename, str):
        raise TypeError("basename must be a string")

    # Helper to create an asset from a file path
    def _create_from_path(name, path):
        if not os.path.isfile(path):
            raise FileNotFoundError(f"File not found: {path}")
        try:
            form = self.get_asset_form_for_create()
            form.set_name(name)
            form.set_file_path(path)
            asset = self.create_asset(form)
            return asset.get_id()
        except Exception as exc:
            raise RuntimeError(f"Failed to create asset for {path}: {exc}") from exc

    # If file_path is a dict mapping filenames to paths, create an asset for each
    if isinstance(file_path, dict):
        asset_ids = []
        for fname, fpath in file_path.items():
            if not isinstance(fname, str) or not isinstance(fpath, str):
                continue  # skip invalid entries
            try:
                asset_id = _create_from_path(basename, fpath)
                asset_ids.append(asset_id)
            except Exception:
                # Skip this file but continue with others
                continue
        return asset_ids

    # Otherwise, file_path should be a single string path
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string or a dict mapping filenames to paths")

    return _create_from_path(basename, file_path)

