def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Map each basename to all file names that share it
            basename_map = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base = os.path.splitext(os.path.basename(name))[0]
                basename_map.setdefault(base, []).append(name)

            # Keep only basenames that have at least one XML file
            for base, files in basename_map.items():
                if any(f.lower().endswith('.xml') for f in files):
                    data = {}
                    for f in files:
                        try:
                            data[f] = zf.read(f)
                        except KeyError:
                            # Skip missing entries
                            continue
                    result[base] = data
    except (FileNotFoundError, zipfile.BadZipFile, OSError):
        # Return empty dict on error
        pass
    return result

