def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None:
        return None
    if not pubdate_xpaths:
        return None

    # Ensure we have an iterable of xpaths
    if not isinstance(pubdate_xpaths, (list, tuple, set)):
        pubdate_xpaths = [pubdate_xpaths]

    for xpath in pubdate_xpaths:
        try:
            # lxml Element
            if hasattr(node, "xpath"):
                matches = node.xpath(xpath)
                if matches:
                    return matches[0]
            # BeautifulSoup
            elif hasattr(node, "select"):
                matches = node.select(xpath)
                if matches:
                    return matches[0]
            # ElementTree
            elif hasattr(node, "find"):
                match = node.find(xpath)
                if match is not None:
                    return match
        except Exception:
            # Skip this xpath if any error occurs
            continue

    # No match found
    return None

