def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        import pprint
        # Validate indent
        if not isinstance(indent, int) or indent < 0:
            indent = 0
        header = ""
        if debug:
            header = f"{type(self).__name__} (id={hex(id(self))})\n"
        try:
            pretty_str = pprint.pformat(self, width=80, indent=indent, compact=False)
        except Exception:
            pretty_str = str(self)
        return header + pretty_str
    except Exception as e:
        return f"<Error pretty printing {type(self).__name__}: {e}>"

