def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be a callable")
    # Determine Python version; fall back to False if PY3 is not defined
    try:
        PY3
    except NameError:
        PY3 = False

    def inner(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception as exc:
            raise RuntimeError(f"Error calling wrapped function: {exc}") from exc

        if PY3:
            # In Python 3, return the result unchanged
            return result
        else:
            # In Python 2, ensure the result is a byte string
            if result is None:
                return None
            if isinstance(result, str):
                try:
                    return result.encode()
                except Exception as exc:
                    raise ValueError(f"Result cannot be encoded to bytes: {exc}") from exc
            elif isinstance(result, bytes):
                # bytes is an alias for str in Python 2, but we keep it for clarity
                return result
            else:
                raise TypeError("Result is not a string and cannot be encoded to bytes")

    return inner

