    default = 'unknown'
    # Attempt to import a module named 'version' and read its __version__ attribute
    try:
        import version
        return getattr(version, '__version__', default)
    except Exception:
        pass

    # Attempt to read a VERSION file or a version.py file
    for path in ('VERSION', 'version.py'):
        try:
            with open(path, 'r') as f:
                content = f.read()
            # If the file is a Python module, look for a __version__ assignment
            if path.endswith('.py'):
                for line in content.splitlines():
                    stripped = line.strip()
                    if stripped.startswith('__version__'):
                        _, val = stripped.split('=', 1)
                        return val.strip().strip('\'"')
            else:
                # For a plain VERSION file, return its stripped content
                return content.strip()
        except Exception:
            continue

    # If all attempts fail, return the default value
    return default

