def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")

    # Build the full command
    full_cmd = cmd_list + list(args)

    # Prepare subprocess parameters
    stderr = subprocess.DEVNULL if hide_stderr else None

    if verbose:
        print("Running command:", " ".join(full_cmd))

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        msg = f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}"
        if e.stdout:
            msg += f"\nStdout: {e.stdout}"
        if e.stderr:
            msg += f"\nStderr: {e.stderr}"
        raise RuntimeError(msg) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error running command '{' '.join(full_cmd)}': {e}") from e

