def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError(f"vcs must be a string, got {type(vcs).__name__}")
    if not isinstance(method, str):
        raise TypeError(f"method must be a string, got {type(method).__name__}")

    def decorator(func):
        """Store func in HANDLERS[vcs][method]."""
        global HANDLERS
        try:
            HANDLERS
        except NameError:
            HANDLERS = {}
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        if not isinstance(HANDLERS[vcs], dict):
            raise ValueError(f"HANDLERS['{vcs}'] must be a dict")
        HANDLERS[vcs][method] = func
        return func

    return decorator

