def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate parameter types
    for name, val in (
        ("validate_objects", validate_objects),
        ("check_digests", check_digests),
        ("show_warnings", show_warnings),
    ):
        if not isinstance(val, bool):
            raise TypeError(f"{name} must be a bool, got {type(val).__name__}")

    # Determine the iterator over hierarchy objects
    if hasattr(self, "_iter_objects"):
        iterator = getattr(self, "_iter_objects")
    elif hasattr(self, "get_objects"):
        iterator = getattr(self, "get_objects")
    else:
        raise AttributeError(
            "Hierarchy object must provide either '_iter_objects' or 'get_objects' method"
        )

    if not callable(iterator):
        raise TypeError("Hierarchy iterator is not callable")

    num_objects = 0
    good_objects = 0

    try:
        for obj in iterator():
            num_objects += 1
            try:
                if validate_objects:
                    if hasattr(obj, "validate"):
                        result = obj.validate()
                        if not result:
                            raise ValueError("Object validation returned False")
                    else:
                        raise AttributeError("Object has no 'validate' method")

                if check_digests:
                    if hasattr(obj, "check_digest"):
                        digest_ok = obj.check_digest()
                        if not digest_ok:
                            raise ValueError("Digest check failed")
                    else:
                        raise AttributeError("Object has no 'check_digest' method")

                good_objects += 1
            except Exception as e:
                if show_warnings:
                    # Use a simple warning output; replace with logging if desired
                    print(f"Warning: object {obj!r} failed validation: {e}")
                # Continue with next object
    except Exception as e:
        # If iteration itself fails, raise a descriptive error
        raise RuntimeError(f"Failed to iterate over hierarchy objects: {e}") from e

    return num_objects, good_objects

