def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    root_inventory = {}
    cumulative_files = set()
    differences = {}  # file -> list of version dirs where digest differs

    for idx, dir_name in enumerate(version_dirs):
        inv_path = os.path.join(dir_name, "inventory.txt")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file in '{dir_name}'")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                lines = f.readlines()
        except Exception as exc:
            raise RuntimeError(f"Failed to read inventory in '{dir_name}': {exc}")

        current_inventory = {}
        for line in lines:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(None, 1)
            if len(parts) != 2:
                raise ValueError(f"Malformed inventory line in '{dir_name}': {line}")
            path, digest = parts
            current_inventory[path] = digest

        # For the first version, establish the root inventory
        if idx == 0:
            root_inventory = current_inventory.copy()
            cumulative_files.update(current_inventory.keys())
        else:
            # Ensure the current inventory contains all files from the root inventory
            missing_root = set(root_inventory.keys()) - set(current_inventory.keys())
            if missing_root:
                raise ValueError(
                    f"Inventory in '{dir_name}' missing files from root inventory: "
                    f"{', '.join(sorted(missing_root))}"
                )

            # Record any digest differences relative to the root inventory
            for path, root_digest in root_inventory.items():
                curr_digest = current_inventory.get(path)
                if curr_digest is None:
                    continue  # already flagged as missing
                if curr_digest != root_digest:
                    differences.setdefault(path, []).append(dir_name)

            # Ensure the current inventory also contains all files added in previous versions
            missing_cumulative = cumulative_files - set(current_inventory.keys())
            if missing_cumulative:
                raise ValueError(
                    f"Inventory in '{dir_name}' missing files from earlier versions: "
                    f"{', '.join(sorted(missing_cumulative))}"
                )

            cumulative_files.update(current_inventory.keys())

    # Store the differences for later validation
    self.different_digests = differences
    return self

