def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate inputs
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        raise ValueError("bug_ids cannot be None")

    # Normalize bug_ids to a list of strings
    if isinstance(bug_ids, (list, tuple, set)):
        ids = list(bug_ids)
    elif isinstance(bug_ids, str):
        # Allow comma‑separated string of ids
        ids = [x.strip() for x in bug_ids.split(',') if x.strip()]
    else:
        ids = [bug_ids]

    if not ids:
        raise ValueError("bug_ids must contain at least one id")

    # Convert all ids to strings (Bugzilla expects string ids)
    ids = [str(i) for i in ids]

    # Merge with existing 'ids' key if present
    if 'ids' in params:
        existing = params['ids']
        if isinstance(existing, (list, tuple)):
            params['ids'] = list(existing) + ids
        else:
            params['ids'] = [existing] + ids
    else:
        params['ids'] = ids

    return params

