def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # None itself is considered a None value
    if val is None:
        return True
    # Only strings can represent a None value in textual form
    if not isinstance(val, str):
        return False
    # Strip whitespace for accurate comparison
    stripped = val.strip()
    # Empty string is considered None
    if not stripped:
        return True
    # Common textual representations of None
    return stripped.lower() in {"none", "null", "na", "n/a"}

