def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("cls must be a class type")
    seen = set()
    stack = [cls]
    while stack:
        parent = stack.pop()
        try:
            children = parent.__subclasses__()
        except Exception:
            continue
        for child in children:
            if child not in seen:
                seen.add(child)
                stack.append(child)
    seen.discard(cls)
    return seen

