def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex

    # Validate input type
    if isinstance(s, bytes):
        try:
            s = s.decode()
        except Exception as exc:
            raise ValueError("bytes input could not be decoded") from exc
    if not isinstance(s, str):
        raise TypeError("s must be a string or bytes, got %r" % type(s).__name__)

    # Determine platform
    if platform == 'this':
        is_windows = sys.platform.startswith('win')
    elif platform == 1:
        is_windows = False
    elif platform == 0:
        is_windows = True
    else:
        raise ValueError("Invalid platform value: %r" % platform)

    try:
        if is_windows:
            return shlex.split(s, posix=False)
        else:
            return shlex.split(s, posix=True)
    except Exception as exc:
        # Fallback: simple split on whitespace
        return s.split()

