def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Direct string checks for common localhost identifiers
    if host.lower() in ("localhost", "127.0.0.1", "::1"):
        return True

    try:
        # Resolve the host to all possible addresses
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Host could not be resolved
        return False

    # Set of known localhost addresses
    localhost_ips = {"127.0.0.1", "::1"}

    for entry in addrinfo:
        # entry[4] contains the socket address tuple; the IP is the first element
        ip = entry[4][0]
        if ip in localhost_ips:
            return True

    return False

