def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, list):
        raise TypeError("commands must be a string or a list of strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    results = []
    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")
        # Build the full command list
        full_cmd = [cmd] + args
        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
                text=True,
                check=True
            )
            if verbose:
                print(result.stdout)
            results.append(result)
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command '{cmd}' failed with return code {e.returncode}")
                print(e.stderr)
            raise
    return results

