def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            yaml_str = yaml.safe_dump(
                obj,
                default_flow_style=False,
                allow_unicode=True
            )
        else:
            yaml_str = yaml.safe_dump(
                obj,
                Dumper=dumper,
                default_flow_style=False,
                allow_unicode=True
            )
    except yaml.YAMLError as exc:
        raise ValueError(f"Error dumping object to YAML string: {exc}") from exc

    # Ensure the result is a unicode string on Python 2
    try:
        import sys
        if sys.version_info[0] < 3 and isinstance(yaml_str, bytes):
            yaml_str = yaml_str.decode("utf-8")
    except Exception:
        pass

    return yaml_str

