def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input x must be numeric array-like.") from e
    mean = 0.2
    sigma = 0.1
    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    return coeff * np.exp(-0.5 * ((x_arr - mean) / sigma) ** 2)

