def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import toml
    import logging

    configs = {}
    error_records = []

    def _create_error_record(filename, exc):
        """Create a LogRecord for a parsing error."""
        msg = f"Failed to parse configuration file '{filename}': {exc}"
        # Use exc_info tuple for the exception
        exc_info = (type(exc), exc, exc.__traceback__)
        return logging.LogRecord(
            name='config_loader',
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc_info
        )

    def _expand_env(value):
        """Recursively expand environment variables in strings."""
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_expand_env(v) for v in value]
        return value

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"File not found: {filename}")

            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()

            # Determine parser based on file extension
            _, ext = os.path.splitext(filename.lower())
            if ext in {'.yaml', '.yml'}:
                config = yaml.safe_load(raw) or {}
            elif ext == '.toml':
                config = toml.loads(raw) or {}
            elif ext == '.json':
                config = json.loads(raw) or {}
            else:
                raise ValueError(f"Unsupported configuration file format: {ext}")

            # Apply overrides if provided
            if overrides:
                if not isinstance(overrides, dict):
                    raise TypeError("Overrides must be a dictionary")
                # Simple shallow merge; nested overrides not handled
                config.update(overrides)

            # Resolve environment variables if requested
            if resolve_env:
                config = _expand_env(config)

            configs[filename] = config

        except Exception as exc:
            error_records.append(_create_error_record(filename, exc))

    return configs, error_records

