def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Helper to get the last field name
    last_field = None
    if hasattr(self, "fields") and isinstance(self.fields, (list, tuple)):
        if self.fields:
            last_field = self.fields[-1]
    if last_field is None:
        # No fields defined; cannot determine scale
        if other is None:
            return None
        raise LenaValueError("Graph has no fields to rescale")

    # Determine current scale
    if isinstance(self.scale, dict):
        current_scale = self.scale.get(last_field)
    else:
        current_scale = self.scale

    if other is None:
        # Return current scale of the last coordinate
        return current_scale

    # Validate that other is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a numeric value or None")

    # Validate current scale
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Graph has unknown or zero scale, cannot rescale")

    # Compute scaling factor
    factor = other / current_scale

    # Apply new scale to the last coordinate
    if isinstance(self.scale, dict):
        self.scale[last_field] = other
    else:
        self.scale = other

    # Rescale associated errors, if any
    if hasattr(self, "errors") and isinstance(self.errors, dict):
        err = self.errors.get(last_field)
        if err is not None:
            if isinstance(err, (list, tuple)):
                self.errors[last_field] = [e * factor for e in err]
            else:
                self.errors[last_field] = err * factor

    return self

