def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # Ensure the cache exists and is not empty
        cache = getattr(self, "_cache", None)
        if not cache:
            raise KeyError("cache is empty")

        # Retrieve frequency structures
        freq_map = getattr(self, "_freq", {})
        min_freq = getattr(self, "_minfreq", None)

        # If min_freq is not set or its bucket is empty, find the next minimum
        if min_freq is None or min_freq not in freq_map or not freq_map[min_freq]:
            if not freq_map:
                raise KeyError("cache is empty")
            min_freq = min(freq_map.keys())

        bucket = freq_map.get(min_freq)
        if not bucket:
            raise KeyError("no items to pop")

        # Pop the first key from the bucket (OrderedDict or list)
        if hasattr(bucket, "popitem"):
            key, _ = bucket.popitem(last=False)
        else:
            # Fallback for plain dict or list
            key = next(iter(bucket))
            bucket.pop(key, None)

        # Remove the key from the main cache
        value = cache.pop(key, None)
        if value is None:
            # Inconsistent state; raise an error
            raise KeyError(f"key {key!r} not found in cache")

        # Clean up the frequency bucket if empty
        if not bucket:
            del freq_map[min_freq]
            # Update minfreq to the next lowest frequency if any
            if freq_map:
                setattr(self, "_minfreq", min(freq_map.keys()))
            else:
                setattr(self, "_minfreq", 0)

        return (key, value)

    except KeyError:
        # Re-raise KeyError unchanged
        raise
    except Exception as exc:
        # Wrap unexpected errors in a generic RuntimeError
        raise RuntimeError(f"Failed to pop least frequently used item: {exc}") from exc

