def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    def _convert(value):
        try:
            if isinstance(value, dict):
                return value
            if isinstance(value, (list, tuple)):
                return dict(value)
            if isinstance(value, str):
                # Split on commas or semicolons, then parse key=value pairs
                pairs = [p.strip() for p in value.replace(';', ',').split(',')]
                result = {}
                for pair in pairs:
                    if not pair:
                        continue
                    if '=' in pair:
                        k, v = pair.split('=', 1)
                        result[k.strip()] = v.strip()
                    else:
                        # Treat as a flag with True value
                        result[pair] = True
                return result
            # Fallback: return the value unchanged
            return value
        except Exception:
            # In case of any unexpected error, return the original value
            return value

    return _converting._Converter(_convert)

