def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Regular expression to match HTTP/HTTPS URLs
    url_re = re.compile(r'(https?://[^\s]+)')
    def _replace(match):
        url = match.group(0)
        # Add desired attributes to the link
        attrs = ' target="_blank" rel="noopener noreferrer"'
        return f'<a href="{url}"{attrs}>{url}</a>'
    try:
        return url_re.sub(_replace, text)
    except Exception as exc:
        # If something goes wrong, raise a runtime error with context
        raise RuntimeError(f"Failed to process links in text: {exc}") from exc

