def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not isinstance(handle, str) or not handle:
            return None
        # Ensure the handle is in the form acct:local@domain
        if '@' not in handle:
            return None
        if not handle.startswith('acct:'):
            resource = f'acct:{handle}'
        else:
            resource = handle
        host = handle.split('@')[-1]
        if not host:
            return None
        url = f'https://{host}/.well-known/webfinger?resource={quote(resource)}'
        with urllib.request.urlopen(url) as resp:
            if resp.status != 200:
                return None
            data = resp.read()
            return data.decode('utf-8', errors='replace')
    except Exception:
        return None

