def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def merge_dicts(dest, src):
        for k, v in src.items():
            if k in dest and isinstance(dest[k], dict) and isinstance(v, dict):
                merge_dicts(dest[k], v)
            else:
                dest[k] = v

    include_key = 'include'
    if include_key not in parser_dict:
        return
    includes = parser_dict.pop(include_key)
    if not isinstance(includes, list):
        raise ValueError("include directive must be a list")
    for inc in includes:
        if isinstance(inc, dict):
            # Recursively resolve nested includes
            self._include_groups(inc)
            merge_dicts(parser_dict, inc)
        else:
            # Treat as a file path; attempt to load JSON or YAML
            try:
                import json
                with open(inc, 'r') as f:
                    try:
                        data = json.load(f)
                    except json.JSONDecodeError:
                        try:
                            import yaml
                            data = yaml.safe_load(f)
                        except Exception as e:
                            raise ValueError(f"Failed to parse {inc} as JSON or YAML: {e}") from e
                if not isinstance(data, dict):
                    raise ValueError(f"Included file {inc} does not contain a dict")
                self._include_groups(data)
                merge_dicts(parser_dict, data)
            except Exception as e:
                raise ValueError(f"Failed to include {inc}: {e}") from e

