def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Iterate over all arguments defined in the scheme
    for arg in getattr(self, "args", []):
        # Skip non-option objects
        if not isinstance(arg, _BaseOpt):
            continue

        # Attempt to fetch a value from the spec if it exists
        spec_val = None
        spec_obj = getattr(self, "spec", None)
        if spec_obj is not None:
            try:
                # Support dict-like spec objects
                if hasattr(spec_obj, "get"):
                    spec_val = spec_obj.get(arg.name)
                else:
                    # Fallback to attribute access
                    spec_val = getattr(spec_obj, arg.name, None)
            except Exception:
                # If spec lookup fails, treat as missing
                spec_val = None

        # If a spec value was found, use it; otherwise fall back to the option's default
        if spec_val is not None:
            defaults[arg.name] = spec_val
        else:
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

        # If the argument is a dictionary option, recursively gather defaults from its scheme
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            sub_defaults = arg.scheme.get_spec_defaults()
            if sub_defaults:
                defaults[arg.name] = sub_defaults

    return defaults

