def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")
    # Resolve the base type
    base_type = spec_option.get('type', str)
    if isinstance(base_type, str):
        type_map = {'int': int, 'float': float, 'str': str, 'bool': bool}
        base_type = type_map.get(base_type, str)
    # Define a callable that performs the parsing/validation
    class ComplexType:
        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option
        def __call__(self, value):
            # Handle list values if requested
            if self.spec_option.get('list'):
                items = [v.strip() for v in value.split(',')]
                try:
                    items = [base_type(v) for v in items]
                except Exception as e:
                    raise ValueError(f"Invalid value for {self.option_name} "
                                     f"in {self.subcommand}: {e}")
                choices = self.spec_option.get('choices')
                if choices is not None:
                    for item in items:
                        if item not in choices:
                            raise ValueError(f"Item {item} for {self.option_name} "
                                             f"in {self.subcommand} not in {choices}")
                return items
            # Handle single value

