    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Define expected types for known parsers. Extend as needed.
    type_map = {
        'main': {
            'port': int,
            'debug': bool,
            'timeout': float,
            'verbose': bool,
        },
        'virsh': {
            'memory': int,
            'cpu': int,
            'name': str,
        },
        'ospd': {
            'config': str,
            'verbose': bool,
            'threads': int,
        },
    }

    parser_map = type_map.get(parser_name, {})
    for key, val in values_dict.items():
        if key not in parser_map:
            continue  # no conversion rule for this key

        target_type = parser_map[key]
        try:
            if target_type is bool:
                # Convert common string representations to bool
                if isinstance(val, bool):
                    continue
                if isinstance(val, str):
                    values_dict[key] = val.lower() in ('true', '1', 'yes', 'on')
                else:
                    values_dict[key] = bool(val)
            elif callable(target_type):
                # If a custom callable is provided, use it
                values_dict[key] = target_type(val)
            else:
                # Standard type conversion
                values_dict[key] = target_type(val)
        except Exception as exc:
            raise ValueError(
                f"Failed to convert argument '{key}' to {target_type}: {exc}"
            ) from exc
    # The function modifies values_dict in place; no return value needed.

